const body = $input.first().json.body || $input.first().json;
const post = body.post || '';
const tech = body.tech || '';
const type = body.type || 'Projet technique';
const postLower = post.toLowerCase();
const techLower = tech.toLowerCase();

let visualType = 'architecture';

if (postLower.includes('conseil') || postLower.includes('astuce') || type.toLowerCase().includes('conseil')) {
  visualType = 'tips';
} else if (postLower.includes('avant') || postLower.includes('before') || postLower.includes('divisé') || postLower.includes('réduit') || postLower.includes('amélioration')) {
  visualType = 'before_after';
} else if (techLower.includes('aws') || techLower.includes('gcp') || techLower.includes('cloud') || techLower.includes('lambda') || techLower.includes('docker') || techLower.includes('kubernetes')) {
  visualType = 'architecture';
} else if (postLower.includes('étape') || postLower.includes('workflow') || postLower.includes('pipeline') || postLower.includes('processus') || techLower.includes('n8n')) {
  visualType = 'flowchart';
} else if (postLower.includes('statistique') || postLower.includes('résultat') || postLower.includes('performance') || postLower.includes('métrique')) {
  visualType = 'stats';
} else {
  visualType = 'architecture';
}

const prompts = {
  architecture: `Tu es un expert en visualisation tech. Génère du HTML/CSS/JS autonome (sans balises html/head/body) qui crée un diagramme d'architecture animé et professionnel pour ce post LinkedIn.

Post: ${post.substring(0, 500)}
Technologies: ${tech}

Règles STRICTES:
- Fond sombre #0f0a2e avec grille subtile
- Boîtes de composants animées qui apparaissent une par une (CSS keyframes)
- Flèches/connexions animées entre composants
- Couleurs: violet #7F77DD, bleu #38bdf8, vert #10b981
- Badges tech en bas
- Largeur fixe 560px hauteur 300px
- Texte blanc, police Inter ou sans-serif
- Animations CSS uniquement (pas de librairies)
- Retourne UNIQUEMENT le HTML/CSS/JS, rien d'autre, pas de markdown`,

  tips: `Tu es un expert en visualisation LinkedIn. Génère du HTML/CSS autonome (sans balises html/head/body) qui crée une carte de conseils animée et professionnelle.

Post: ${post.substring(0, 500)}
Technologies: ${tech}

Règles STRICTES:
- Fond dégradé sombre #0f2818 vers #0a1f12
- 3-4 conseils extraits du post, numérotés, qui apparaissent avec animation décalée (stagger)
- Numéros avec fond vert #10b981
- Icônes simples CSS (checkmarks, arrows)
- Largeur fixe 560px hauteur 300px
- Texte blanc, police Inter ou sans-serif
- Animations CSS keyframes uniquement
- Retourne UNIQUEMENT le HTML/CSS, rien d'autre, pas de markdown`,

  before_after: `Tu es un expert en visualisation LinkedIn. Génère du HTML/CSS/JS autonome (sans balises html/head/body) qui crée un visuel before/after animé et professionnel.

Post: ${post.substring(0, 500)}
Technologies: ${tech}

Règles STRICTES:
- Fond sombre #0f0a2e
- Deux colonnes: AVANT (rouge/problème) et APRÈS (vert/solution)
- Chiffres/métriques extraits du post qui comptent avec animation JS
- Séparateur central avec flèche animée
- Largeur fixe 560px hauteur 300px
- Texte blanc, police Inter ou sans-serif
- Animations CSS + compteur JS
- Retourne UNIQUEMENT le HTML/CSS/JS, rien d'autre, pas de markdown`,

  flowchart: `Tu es un expert en visualisation LinkedIn. Génère du HTML/CSS/JS autonome (sans balises html/head/body) qui crée un flowchart de pipeline animé et professionnel.

Post: ${post.substring(0, 500)}
Technologies: ${tech}

Règles STRICTES:
- Fond sombre #0f0a2e avec grille
- Étapes du pipeline qui s'allument une par une avec délai
- Flèches CSS entre les étapes
- Chaque étape: icon + label + tech utilisée
- Couleurs progressives du violet au bleu au vert
- Largeur fixe 560px hauteur 300px
- Animations CSS keyframes avec délais décalés
- Retourne UNIQUEMENT le HTML/CSS/JS, rien d'autre, pas de markdown`,

  stats: `Tu es un expert en visualisation LinkedIn. Génère du HTML/CSS/JS autonome (sans balises html/head/body) qui crée un dashboard de métriques animé et professionnel.

Post: ${post.substring(0, 500)}
Technologies: ${tech}

Règles STRICTES:
- Fond sombre #0f0a2e
- 3-4 métriques/stats extraites du post
- Barres de progression ou chiffres qui s'animent (compteur JS)
- Icônes CSS simples pour chaque métrique
- Couleurs: violet, bleu, vert, orange
- Largeur fixe 560px hauteur 300px
- Animations CSS + compteur JS
- Retourne UNIQUEMENT le HTML/CSS/JS, rien d'autre, pas de markdown`
};

return [{ json: { post, tech, type, visualType, prompt: prompts[visualType] } }];

const response = $input.first().json;
const prev = $('Analyze & Build Prompt').first().json;

let htmlCode = '';
try {
  htmlCode = response.choices[0].message.content;
  // Nettoyer les balises markdown si présentes
  htmlCode = htmlCode.replace(/```html/gi, '').replace(/```css/gi, '').replace(/```js/gi, '').replace(/```javascript/gi, '').replace(/```/g, '').trim();
  // Supprimer les balises html/head/body si l'IA les a ajoutées quand même
  htmlCode = htmlCode.replace(/<\/?html[^>]*>/gi, '').replace(/<\/?head[^>]*>[\s\S]*?<\/head>/gi, '').replace(/<\/?body[^>]*>/gi, '').trim();
} catch(e) {
  htmlCode = '<div style="color:white;padding:20px">Erreur de génération</div>';
}

return [{
  json: {
    success: true,
    visualType: prev.visualType,
    htmlCode,
    generatedAt: new Date().toISOString()
  }
}];
